create extension if not exists pgcrypto;
create table public.products (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, description text not null, is_active boolean not null default true, created_at timestamptz not null default now());
create table public.product_variants (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id), sku text unique not null, size text not null, color text not null, price_centavos integer not null check (price_centavos >= 0), is_active boolean not null default true);
create table public.inventory (variant_id uuid primary key references public.product_variants(id), available_quantity integer not null default 0 check (available_quantity >= 0), updated_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(), order_number text unique not null, email text not null, full_name text not null, mobile text not null, shipping_address jsonb not null, subtotal_centavos integer not null check (subtotal_centavos >= 0), shipping_centavos integer not null check (shipping_centavos >= 0), total_centavos integer not null check (total_centavos >= 0), payment_status text not null default 'pending' check (payment_status in ('pending','paid','failed','refunded','partially_refunded')), fulfillment_status text not null default 'pending' check (fulfillment_status in ('pending','processing','packed','shipped','delivered','cancelled')), created_at timestamptz not null default now());
create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id), variant_id uuid references public.product_variants(id), product_name text not null, sku text not null, size text not null, color text not null, unit_price_centavos integer not null, quantity integer not null check (quantity > 0), line_total_centavos integer not null);
alter table public.products enable row level security; alter table public.product_variants enable row level security; alter table public.inventory enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security;
create policy "public reads active products" on public.products for select using (is_active); create policy "public reads active variants" on public.product_variants for select using (is_active); create policy "public reads inventory" on public.inventory for select using (true);
